import{_ as e}from"./chunks/introduction.B_4Vv96H.js";import{_ as a,o as r,c as o,a5 as i}from"./chunks/framework.DGp912Ge.js";const u=JSON.parse('{"title":"RBQGUI","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/introduction.md","filePath":"ko/manual/gui/introduction.md","lastUpdated":1785806767000}'),d={name:"ko/manual/gui/introduction.md"};function n(l,t,s,c,g,h){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="rbqgui" tabindex="-1">RBQGUI <a class="header-anchor" href="#rbqgui" aria-label="Permalink to &quot;RBQGUI&quot;">​</a></h1><h2 id="downloads" tabindex="-1">다운로드 <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;다운로드 {#downloads}&quot;">​</a></h2><p>RBQGUI 설치 파일(Linux AppImage · Android APK)은 <strong><a href="/RBQ/ko/manual/downloads/">다운로드</a></strong> 페이지에서 받으실 수 있습니다.</p><h2 id="소개" tabindex="-1">소개 <a class="header-anchor" href="#소개" aria-label="Permalink to &quot;소개&quot;">​</a></h2><p><strong>RBQGUI</strong>는 RBQ 4족 보행 로봇을 PC나 컨트롤러에서 원격으로 제어·모니터링하기 위한 전용 애플리케이션입니다. 로봇과 연결한 뒤 화면에서 자세(앉기·서기·보행 등)를 바꾸고, 3D 가상 뷰나 카메라 영상으로 주변 상황을 확인할 수 있습니다.</p><ul style="margin-bottom:0.75rem;padding-left:1.25rem;"><li><strong>연결</strong>: 로봇과 동일 네트워크로 통신합니다.</li><li><strong>제어</strong>: 보행 모드·계단·도킹 등 동작 모드를 선택하고, 조이스틱으로 이동·자세를 조작합니다.</li><li><strong>모니터링</strong>: 배터리·연결 상태 등을 화면에서 확인할 수 있습니다.</li></ul><p style="margin-top:0;margin-bottom:0.35rem;">아래는 RBQGUI 실행 후 보이는 대표 화면입니다.</p><figure style="margin-top:0;text-align:center;"><img src="'+e+'" alt="RBQGUI 대표 화면" style="display:block;margin:0 auto;transform:scale(1);transform-origin:center top;"><figcaption style="text-align:center;margin-top:0.5rem;">&lt;RBQGUI 대표 화면&gt;</figcaption></figure><h2 id="버튼-설명-1-9" tabindex="-1">버튼 설명 (1~9) <a class="header-anchor" href="#버튼-설명-1-9" aria-label="Permalink to &quot;버튼 설명 (1~9)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">번호</th><th>기능</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><code>Sit</code> 모드: 로봇을 앉은 자세로 유지</td></tr><tr><td style="text-align:right;">2</td><td><code>Stance</code> 모드: 일어나서 기본 자세로 전환</td></tr><tr><td style="text-align:right;">3</td><td><code>Walk</code> 모드: 보행(전진/후진, 좌/우 이동 및 회전)</td></tr><tr><td style="text-align:right;">4</td><td><code>Stair</code> 모드: 계단 조건에 맞춰 보행 동작 수행</td></tr><tr><td style="text-align:right;">5</td><td><code>Docking</code> 모드: 충전 스테이션에 정렬해 도킹 시도</td></tr><tr><td style="text-align:right;">6</td><td><code>RL (Vision Trot)</code> 모드: 강화학습 보행 수행</td></tr><tr><td style="text-align:right;">7</td><td><code>Walking Parameter Setting</code> 모드: 보행 파라미터(속도/몸체 높이/발 높이 등) 조정</td></tr><tr><td style="text-align:right;">8</td><td><code>3D Virtual View</code> 모드: 로봇의 3D 가상 뷰로 전환</td></tr><tr><td style="text-align:right;">9</td><td><code>Camera View</code> 모드: 카메라(실영상) 화면으로 전환</td></tr></tbody></table><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>로봇의 자세가 변경되거나 앱 화면이 전환되면, 해당 버튼이 주황색으로 변합니다.</p></div></div>',11)])])}const b=a(d,[["render",n]]);export{u as __pageData,b as default};
